using HRIS.Api.Common; using HRIS.Api.DTOs.Laptop; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Repositories;
namespace HRIS.Api.Services; public class LaptopService:ILaptopService { private readonly ILaptopRepository _repo; private readonly IApprovalService _approval; private readonly IReferenceRepository _refs; private readonly IEmployeeRepository _employees; private readonly IAuditLogService _audit; public LaptopService(ILaptopRepository repo,IApprovalService approval,IAuditLogService audit,IReferenceRepository refs,IEmployeeRepository employees){_repo=repo;_approval=approval;_audit=audit;_refs=refs;_employees=employees;} public async Task<List<LaptopResponseDto>> GetAsync(UserContext actor){var rows=await _repo.GetAllAsync(actor.IsHrOrSupport?null:actor.EmployeeId);var apps=await _approval.GetByRefsAsync(ApprovalRequestTypes.Laptop,rows.Select(x=>x.Id),actor);return rows.Select(x=>ToDto(x,apps.GetValueOrDefault(x.Id)?.Id)).ToList();} public async Task<LaptopResponseDto> CreateAsync(LaptopCreateDto dto,UserContext actor){var emp=actor.EmployeeId??throw new ForbiddenException("Akun ini tidak terhubung ke Employee.");var employee=await _employees.GetByIdAsync(emp)??throw new NotFoundException("Employee tidak ditemukan.");var currentEmployment=employee.Employments.FirstOrDefault(x=>x.EndDate==null);if(currentEmployment is not null&&!await _refs.IsModuleAllowedAsync(currentEmployment.EmploymentTypeId,"10"))throw new ForbiddenException("Karyawan dengan tipe pekerjaan saat ini tidak mendapatkan modul Laptop Ownership.");if(dto.Price is < 0)throw new BadRequestException("Harga tidak boleh negatif.");var x=await _repo.AddAsync(new LaptopRequest{EmployeeId=emp,Model=dto.Model.Trim(),Price=dto.Price,Status="Submitted"});await _repo.AddLogAsync(new LaptopStatusLog{LaptopId=x.Id,Status="Submitted",ChangedBy=actor.UserId,Note="Pengajuan dibuat"});var app=await _approval.SubmitAsync(ApprovalRequestTypes.Laptop,x.Id,emp,$"Permintaan laptop {x.Model}");return ToDto(await _repo.GetByIdAsync(x.Id)!,app.Id);} public async Task UpdateStatusAsync(int id,string status,string? note,UserContext actor){if(!actor.IsHrOrSupport)throw new ForbiddenException("Hanya HR/Support yang boleh mengubah status laptop.");var x=await _repo.GetByIdAsync(id)??throw new NotFoundException("Permintaan laptop tidak ditemukan.");status=status.Trim();var allowed=new Dictionary<string,string[]>{["ForwardedToIT"]=new[]{"Submitted"},["Purchased"]=new[]{"Approved"},["ResetDone"]=new[]{"Purchased"}};if(!allowed.TryGetValue(status,out var from)||!from.Contains(x.Status))throw new BadRequestException($"Transisi {x.Status} ke {status} tidak valid.");x.Status=status;await _repo.UpdateAsync(x);await _repo.AddLogAsync(new LaptopStatusLog{LaptopId=x.Id,Status=status,ChangedBy=actor.UserId,Note=note});if(actor.IsSupport)await _audit.LogAsync(actor.UserId,"Laptop.Status",nameof(LaptopRequest),id,$"Status menjadi {status}");} private static LaptopResponseDto ToDto(LaptopRequest x,int? aid)=>new(){Id=x.Id,EmployeeId=x.EmployeeId,EmployeeName=x.Employee?.FullName??"",AssetTag=x.AssetTag,Model=x.Model,Price=x.Price,Status=x.Status,CreatedAt=x.CreatedAt,ApprovalId=aid,Logs=x.StatusLogs.OrderBy(l=>l.ChangedAt).Select(l=>new LaptopStatusLogResponseDto{Id=l.Id,Status=l.Status,ChangedBy=l.ChangedBy,ChangedByName=l.ChangedByUser?.Username??"",ChangedAt=l.ChangedAt,Note=l.Note}).ToList()}; }
